declare(strict_types=1); require_once __DIR__.'/_helper.php'; konsultasi_require_access($pdo); $tapel=konsultasi_tapel($pdo); $tid=(int)($tapel['id']??0); $q=trim((string)($_GET['q']??''));
$sql="SELECT k.*,s.nis,s.nisn,s.nama,mk.nama kelas,g.nama petugas FROM konsultasi_bk k JOIN siswa s ON s.id=k.siswa_id LEFT JOIN guru g ON g.id=k.petugas_id LEFT JOIN siswa_kelas sk ON sk.id=(SELECT sk2.id FROM siswa_kelas sk2 WHERE sk2.siswa_id=s.id AND sk2.tahun_pelajaran_id=k.tahun_pelajaran_id AND sk2.status='aktif' ORDER BY sk2.id DESC LIMIT 1) LEFT JOIN master_kelas mk ON mk.id=sk.kelas_id WHERE k.tahun_pelajaran_id=?"; $p=[$tid]; if($q!==''){ $sql.=" AND (s.nama LIKE ? OR s.nis LIKE ? OR s.nisn LIKE ? OR k.topik LIKE ?)"; $x='%'.$q.'%';$p=[$tid,$x,$x,$x,$x]; } $sql.=' ORDER BY k.tanggal DESC,k.id DESC'; $st=$pdo->prepare($sql);$st->execute($p);$rows=$st->fetchAll();
$page_title='Konsultasi'; require_once __DIR__.'/../layouts/header.php';require_once __DIR__.'/../layouts/sidebar.php'; ?>
