<form class="dashboard-table-card" method="get" style="margin-bottom:16px"><div style="display:flex;gap:10px"><input class="form-control" name="q" value="<?=e($q)?>" placeholder="Cari nama, NIS, NISN, atau topik..."><button class="btn btn-secondary"><i class="bi bi-search"></i> Cari</button></div></form>
<div class="dashboard-table-card"><div class="table-responsive"><table class="data-table"><thead><tr><th>Tanggal</th><th>Siswa</th><th>Kelas</th><th>Jenis</th><th>Topik</th><th>Status</th><th>Petugas</th><th></th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="8" class="empty-state">Belum ada data konsultasi.</td></tr><?php else:foreach($rows as $r):?><tr><td><?=e($r['tanggal'])?></td><td><strong><?=e($r['nama'])?></strong><br><small><?=e($r['nis'])?></small></td><td><?=e($r['kelas']??'-')?></td><td><?=e(ucwords(str_replace('_',' ',$r['jenis'])))?></td><td><?=e($r['topik'])?></td><td><?=e(ucfirst($r['status']))?></td><td><?=e($r['petugas']??'-')?></td><td><a class="btn btn-sm btn-secondary" href="<?=BASE_URL?>konsultasi/detail.php?id=<?=$r['id']?>"><i class="bi bi-eye"></i></a></td></tr><?php endforeach;endif;?></tbody></table></div></div></section></main><?php require_once __DIR__.'/../layouts/footer.php';?>
